#if DEBUG
import Foundation
import ImageIO
import UIKit

// MARK: - Synthetic radar (oscar-server frames/grid/tiles/motion/cells)

/// Deterministic fake precipitation for the map and widget scenes: one real
/// radar composite (see `bakedFieldBase64`), replayed over the German box and
/// advected SW→NE per frame so the timeline animates. Value noise stood in
/// here before and never looked like weather — real echoes have the cores,
/// holes and shower clusters that noise can't fake. The same field feeds the
/// fullscreen map's value grid, the widget's raster tiles, and the motion
/// arrows.
enum SyntheticRadar {
    static let north = 55.6, south = 46.0, west = 3.6, east = 17.8
    /// The latest observation plus the two-hour nowcast oscar-server relays
    /// from the DWD RV product, in 5-minute steps; the key encodes the offset.
    /// No past frames: the map opens on the frame nearest the real device
    /// clock, which for a story dated tomorrow is always the oldest one, so the
    /// oldest frame has to BE the story's "now" for the scrubber to read right.
    static let offsets = Array(stride(from: 0, through: 120, by: 5))
    /// Matches the baked field's own resolution (50 px per degree) — a coarser
    /// grid than that shows as visible blocks under the map's linear filtering.
    static let gridWidth = 710, gridHeight = 500

    static func key(_ offset: Int) -> String { "fx\(offset)" }
    static func offsetMinutes(fromKey key: String) -> Double? {
        key.hasPrefix("fx") ? Double(key.dropFirst(2)) : nil
    }

    // MARK: JSON endpoints

    static func framesJSON() -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        // Same story clock as the forecast fixtures, so the scrubber's labels
        // read the same early afternoon the sky and hourly strip do.
        let now = ScreenshotFixtures.storyNow
        let bounds: [String: Any] = ["north": north, "south": south, "west": west, "east": east]
        return [
            "generated_at": formatter.string(from: now),
            "frame_count": offsets.count,
            "frames": offsets.enumerated().map { index, offset in
                [
                    "key": key(offset),
                    "timestamp": formatter.string(from: now.addingTimeInterval(Double(offset) * 60)),
                    "source": "dwd",
                    "index": index,
                    "is_forecast": offset > 0,
                ]
            },
            "bounds": bounds,
            "image_bounds": bounds,
        ]
    }

    static func cellsJSON() -> [String: Any] {
        ["type": "FeatureCollection", "features": [] as [Any]]
    }

    /// One shared coarse flow field, SW→NE like the band's advection.
    static func motionJSON() -> [String: Any] {
        let cols = 8, rows = 8
        var values = [Int16](repeating: 70, count: cols * rows)          // u: east (×0.05 px/step)
        values.append(contentsOf: [Int16](repeating: -40, count: cols * rows))  // v: north
        let data = values.withUnsafeBufferPointer { Data(buffer: $0) }
        let pairs: [[String: Any]] = (0..<(offsets.count - 1)).map {
            ["from": key(offsets[$0]), "to": key(offsets[$0 + 1]), "field": 0, "gap_minutes": 5]
        }
        return [
            "cols": cols, "rows": rows,
            "overview_width": gridWidth, "overview_height": gridHeight,
            "scale": 0.05, "step_minutes": 5,
            "fields": [data.base64EncodedString()],
            "pairs": pairs,
        ]
    }

    // MARK: Field

    /// The baked field covers the served bounds plus this margin on every side
    /// — the room the -60…+120 min advection sweep needs to stay on real data.
    private static let fieldMarginLon = 1.9, fieldMarginLat = 1.2

    private struct Field {
        let values: [UInt8]
        /// Fraction of echo in a wide neighbourhood, the cloud deck's proxy.
        let coverage: [UInt8]
        let width: Int
        let height: Int
    }

    nonisolated(unsafe) private static var cachedField: Field?

    private static func field() -> Field {
        cacheLock.lock()
        defer { cacheLock.unlock() }
        if let cachedField { return cachedField }
        let resolved = decodeBakedField() ?? Field(values: [0], coverage: [0], width: 1, height: 1)
        cachedField = resolved
        return resolved
    }

    private static func decodeBakedField() -> Field? {
        guard let data = Data(base64Encoded: bakedFieldBase64),
              let image = UIImage(data: data)?.cgImage else { return nil }
        let w = image.width, h = image.height
        var values = [UInt8](repeating: 0, count: w * h)
        let drawn = values.withUnsafeMutableBytes { raw -> Bool in
            guard let context = CGContext(
                data: raw.baseAddress, width: w, height: h,
                bitsPerComponent: 8, bytesPerRow: w,
                space: CGColorSpaceCreateDeviceGray(),
                bitmapInfo: CGImageAlphaInfo.none.rawValue
            ) else { return false }
            context.draw(image, in: CGRect(x: 0, y: 0, width: CGFloat(w), height: CGFloat(h)))
            return true
        }
        guard drawn else { return nil }
        return Field(values: values, coverage: coverageMask(values, width: w, height: h),
                     width: w, height: h)
    }

    /// Separable box blur over the echo mask: 0 = clear sky, 255 = solid echo
    /// across the whole window. Radius ≈ 0.5°, so the deck reaches well past
    /// the rain the way real cloud does.
    private static func coverageMask(_ values: [UInt8], width w: Int, height h: Int) -> [UInt8] {
        let radius = 16
        var rows = [Float](repeating: 0, count: w * h)
        for j in 0..<h {
            var sum: Float = 0
            for i in -radius...radius where i >= 0 && i < w {
                sum += values[j * w + i] > 0 ? 1 : 0
            }
            for i in 0..<w {
                rows[j * w + i] = sum / Float(2 * radius + 1)
                let leaving = i - radius, entering = i + radius + 1
                if leaving >= 0 { sum -= values[j * w + leaving] > 0 ? 1 : 0 }
                if entering < w { sum += values[j * w + entering] > 0 ? 1 : 0 }
            }
        }
        var out = [UInt8](repeating: 0, count: w * h)
        for i in 0..<w {
            var sum: Float = 0
            for j in -radius...radius where j >= 0 && j < h {
                sum += rows[j * w + i]
            }
            for j in 0..<h {
                out[j * w + i] = UInt8(min(255, sum / Float(2 * radius + 1) * 255))
                let leaving = j - radius, entering = j + radius + 1
                if leaving >= 0 { sum -= rows[leaving * w + i] }
                if entering < h { sum += rows[entering * w + i] }
            }
        }
        return out
    }

    /// Bilinear sample of one baked plane at an advected coordinate.
    private static func sample(
        _ plane: KeyPath<Field, [UInt8]>,
        lat: Double,
        lon: Double,
        minutes t: Double
    ) -> Double {
        let field = field()
        guard field.width > 1 else { return 0 }
        let ax = lon - t * 0.011
        let ay = lat - t * 0.006
        let fieldWest = west - fieldMarginLon, fieldEast = east + fieldMarginLon
        let fieldSouth = south - fieldMarginLat, fieldNorth = north + fieldMarginLat
        let fx = (ax - fieldWest) / (fieldEast - fieldWest) * Double(field.width - 1)
        let fy = (fieldNorth - ay) / (fieldNorth - fieldSouth) * Double(field.height - 1)
        guard fx >= 0, fy >= 0, fx <= Double(field.width - 1), fy <= Double(field.height - 1) else { return 0 }
        let x0 = Int(fx), y0 = Int(fy)
        let x1 = min(x0 + 1, field.width - 1), y1 = min(y0 + 1, field.height - 1)
        let tx = fx - Double(x0), ty = fy - Double(y0)
        let values = field[keyPath: plane]
        let a = Double(values[y0 * field.width + x0]), b = Double(values[y0 * field.width + x1])
        let c = Double(values[y1 * field.width + x0]), d = Double(values[y1 * field.width + x1])
        return (a + (b - a) * tx) * (1 - ty) + (c + (d - c) * tx) * ty
    }

    /// Cloud opacity 0…1: the echo's own intensity plus the much wider deck
    /// around it (rain implies cloud; cloud reaches far beyond the rain).
    static func cloudOpacity(lat: Double, lon: Double, minutes t: Double) -> Double {
        let deck = sample(\.coverage, lat: lat, lon: lon, minutes: t) / 255
        return min(1, deck * 1.6 + intensity(lat: lat, lon: lon, minutes: t) * 1.5)
    }

    /// Intensity 0…1 at a coordinate, advected SW→NE over time. The baked
    /// bytes are the server's own palette indices, so `gridPNG` re-encoding
    /// them lands back on the value they were captured with.
    static func intensity(lat: Double, lon: Double, minutes t: Double) -> Double {
        let index = sample(\.values, lat: lat, lon: lon, minutes: t)
        return min(1, max(0, (index - 1) / 219))
    }

    // MARK: Mercator helpers

    private static func mercY(_ lat: Double) -> Double {
        log(tan(.pi / 4 + lat * .pi / 360))
    }
    private static func latFromMercY(_ y: Double) -> Double {
        (2 * atan(exp(y)) - .pi / 2) * 180 / .pi
    }

    // MARK: Value grid (fullscreen map's Metal layer)

    /// URLProtocol loads on arbitrary threads — guard the render caches.
    private static let cacheLock = NSLock()
    nonisolated(unsafe) private static var gridCache: [String: Data] = [:]

    /// Single-channel 8-bit grid in Web Mercator rows (row 0 = north), like the
    /// server's lossless WebP — `UIImage(data:)` decodes PNG just the same.
    /// 0 = dry, values over the plasma dBZ ramp.
    static func gridPNG(frameKey: String) -> Data {
        let cacheKey = frameKey
        cacheLock.lock()
        if let cached = gridCache[cacheKey] { cacheLock.unlock(); return cached }
        cacheLock.unlock()
        let t = offsetMinutes(fromKey: frameKey) ?? 0
        let w = gridWidth, h = gridHeight
        var pixels = [UInt8](repeating: 0, count: w * h)
        let mN = mercY(north), mS = mercY(south)
        for j in 0..<h {
            let lat = latFromMercY(mN + (mS - mN) * Double(j) / Double(h))
            for i in 0..<w {
                let lon = west + (east - west) * Double(i) / Double(w)
                let v = intensity(lat: lat, lon: lon, minutes: t)
                guard v >= 0.02 else { continue }
                pixels[j * w + i] = UInt8(1 + min(219, v * 219))
            }
        }
        let png = grayPNG(pixels: pixels, width: w, height: h)
        cacheLock.lock()
        gridCache[cacheKey] = png
        cacheLock.unlock()
        return png
    }

    /// Clouds flavor of the value grid: opacity index 0…255 (the clouds palette
    /// contract), from `cloudOpacity`'s wider deck.
    static func cloudGridPNG(frameKey: String) -> Data {
        let cacheKey = "\(frameKey)|clouds"
        cacheLock.lock()
        if let cached = gridCache[cacheKey] { cacheLock.unlock(); return cached }
        cacheLock.unlock()
        let t = offsetMinutes(fromKey: frameKey) ?? 0
        let w = gridWidth, h = gridHeight
        var pixels = [UInt8](repeating: 0, count: w * h)
        let mN = mercY(north), mS = mercY(south)
        for j in 0..<h {
            let lat = latFromMercY(mN + (mS - mN) * Double(j) / Double(h))
            for i in 0..<w {
                let lon = west + (east - west) * Double(i) / Double(w)
                let v = cloudOpacity(lat: lat, lon: lon, minutes: t)
                guard v >= 0.03 else { continue }
                pixels[j * w + i] = UInt8(min(255, 40 + v * 215))
            }
        }
        let png = grayPNG(pixels: pixels, width: w, height: h)
        cacheLock.lock()
        gridCache[cacheKey] = png
        cacheLock.unlock()
        return png
    }

    private static func grayPNG(pixels: [UInt8], width: Int, height: Int) -> Data {
        var pixels = pixels
        let image = pixels.withUnsafeMutableBytes { raw -> CGImage? in
            let context = CGContext(
                data: raw.baseAddress, width: width, height: height,
                bitsPerComponent: 8, bytesPerRow: width,
                space: CGColorSpaceCreateDeviceGray(),
                bitmapInfo: CGImageAlphaInfo.none.rawValue
            )
            return context?.makeImage()
        }
        guard let image else { return Data() }
        return UIImage(cgImage: image).pngData() ?? Data()
    }

    // MARK: Raster tiles (widget composite + precip gate)

    nonisolated(unsafe) private static var tileCache: [String: Data] = [:]

    /// The widget reverse-maps tile colors to palette indices through the
    /// server colormap (data-space smoothing), so tile pixels must BE palette
    /// entries — hand-approximated colors snap to wrong (purple) indices.
    /// Colormaps pass through the fixture server live; fetch the real plasma
    /// palette once and build tiles from it with the exact grid index math,
    /// which makes the widget match the fullscreen map by construction.
    nonisolated(unsafe) private static var cachedPalette: [UInt8]?
    private static func plasmaPalette() -> [UInt8] {
        cacheLock.lock()
        if let cached = cachedPalette { cacheLock.unlock(); return cached }
        cacheLock.unlock()
        final class Box: @unchecked Sendable { var data: [UInt8]? }
        let box = Box()
        if let url = URL(string: "\(radarBaseURL)/colormaps/plasma") {
            let semaphore = DispatchSemaphore(value: 0)
            URLSession.shared.dataTask(with: url) { data, _, _ in
                if let data, data.count >= 256 * 4 { box.data = [UInt8](data.prefix(256 * 4)) }
                semaphore.signal()
            }.resume()
            _ = semaphore.wait(timeout: .now() + 10)
        }
        // Offline fallback: approximated plasma with a hard alpha ramp.
        let resolved = box.data ?? (0..<256).flatMap { i -> [UInt8] in
            guard i > 0 else { return [0, 0, 0, 0] }
            let t = Double(i - 1) / 254
            let (r, g, b) = plasma(t)
            return [UInt8(r), UInt8(g), UInt8(b), UInt8(min(235, 70 + t * 400))]
        }
        cacheLock.lock()
        cachedPalette = resolved
        cacheLock.unlock()
        return resolved
    }

    /// Raster tile like the server's: the value grid's palette index per
    /// pixel, colorized through the shared colormap (premultiplied).
    static func tilePNG(frameKey: String, z: Int, x: Int, y: Int) -> Data {
        let cacheKey = "\(frameKey)|\(z)/\(x)/\(y)"
        cacheLock.lock()
        if let cached = tileCache[cacheKey] { cacheLock.unlock(); return cached }
        cacheLock.unlock()
        let t = offsetMinutes(fromKey: frameKey) ?? 0
        let palette = plasmaPalette()
        let size = 256
        let n = pow(2.0, Double(z))
        var pixels = [UInt8](repeating: 0, count: size * size * 4)
        for j in 0..<size {
            let yTile = (Double(y) + Double(j) / Double(size)) / n
            let lat = latFromMercY(.pi * (1 - 2 * yTile))
            for i in 0..<size {
                let lon = (Double(x) + Double(i) / Double(size)) / n * 360 - 180
                let v = intensity(lat: lat, lon: lon, minutes: t)
                guard v >= 0.02 else { continue }
                // Same index math as gridPNG, so tiles == fullscreen grid.
                let index = Int(1 + min(219, v * 219))
                let p = index * 4
                let o = (j * size + i) * 4
                // Straight (non-premultiplied) palette RGBA, exactly like the
                // server's tiles: PNG stores unpremultiplied, and the widget's
                // reverse LUT expects pixels that ARE palette entries.
                pixels[o] = palette[p]
                pixels[o + 1] = palette[p + 1]
                pixels[o + 2] = palette[p + 2]
                pixels[o + 3] = palette[p + 3]
            }
        }
        // Encode via ImageIO from a non-premultiplied CGImage — a CGContext
        // round-trip would premultiply and lose the exact palette values.
        guard let provider = CGDataProvider(data: Data(pixels) as CFData),
              let image = CGImage(
                  width: size, height: size, bitsPerComponent: 8, bitsPerPixel: 32,
                  bytesPerRow: size * 4, space: CGColorSpace(name: CGColorSpace.sRGB)!,
                  bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.last.rawValue),
                  provider: provider, decode: nil, shouldInterpolate: false,
                  intent: .defaultIntent),
              let png = pngData(from: image) else {
            return Data()
        }
        cacheLock.lock()
        tileCache[cacheKey] = png
        cacheLock.unlock()
        return png
    }

    private static func pngData(from image: CGImage) -> Data? {
        let output = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(
            output, "public.png" as CFString, 1, nil) else { return nil }
        CGImageDestinationAddImage(destination, image, nil)
        guard CGImageDestinationFinalize(destination) else { return nil }
        return output as Data
    }

    /// One real oscar-server value grid — NOAA MRMS, 2026-08-14T20:44Z, an
    /// afternoon of scattered convection over the western US — cropped to an
    /// 18° × 12° box at native resolution (900×784), posterized to 64 levels:
    /// 8-bit palette indices, PNG, base64. Any composite with good structure
    /// works (OPERA over Scandinavia was the runner-up, all stratiform teal —
    /// convective cells read as radar much more clearly). Regenerate with:
    ///
    ///     curl -s "$OSCAR/radar/usa/frames" | jq -r '.frames[] | select(.is_forecast|not) | .key' | tail -1
    ///     curl -s "$OSCAR/radar/usa/frames/<key>/grid" -o src.webp
    ///     magick src.webp -background black -alpha remove -alpha off -colorspace gray \
    ///       -crop 900x784+440+500 +repage -posterize 64 field.png
    ///     base64 -i field.png
    ///
    /// The crop is in that grid's pixels: x = (lon − west) × width / lonSpan,
    /// y = (north − lat) × height / latSpan, sized to the served box plus the
    /// margin above. Aim the window so a cell cluster lands ~59 % across and
    /// ~46 % down — that is where the Leipzig pin sits.
    private static let bakedFieldBase64 = ""

    private static func plasma(_ v: Double) -> (Int, Int, Int) {
        let stops: [(Double, (Double, Double, Double))] = [
            (0.00, (13, 8, 135)), (0.25, (126, 3, 168)), (0.50, (204, 71, 120)),
            (0.75, (248, 149, 64)), (1.00, (240, 249, 33)),
        ]
        for i in 0..<(stops.count - 1) {
            let (a, ca) = stops[i], (b, cb) = stops[i + 1]
            if v <= b {
                let f = (v - a) / (b - a)
                return (Int(ca.0 + (cb.0 - ca.0) * f), Int(ca.1 + (cb.1 - ca.1) * f), Int(ca.2 + (cb.2 - ca.2) * f))
            }
        }
        return (240, 249, 33)
    }
}
#endif
